import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  // NOTE: no app.set('trust proxy', <hopCount>) here — Express/Nest has no
  // notion of how many proxy hops are "ours", so it cannot tell an
  // infrastructure-appended X-Forwarded-For entry from a client-supplied one.
  app.enableCors();
  await app.listen(3000);
}
