// ---------- login-rate-limit.guard.ts ----------
import {
  CanActivate,
  ExecutionContext,
  Injectable,
  TooManyRequestsException,
} from '@nestjs/common';
import { Request } from 'express';
import { RateLimitService } from './rate-limit.service';

@Injectable()
export class LoginRateLimitGuard implements CanActivate {
  constructor(private readonly rateLimitService: RateLimitService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const request = context.switchToHttp().getRequest<Request>();

    const fwd = request.headers['x-forwarded-for'] as string | undefined;
    // Takes the left-most entry as "the real client IP". That entry is the
    // FIRST one written on the wire — i.e. whatever the caller itself sends —
    // so an attacker can put any string there.
    const clientIp = fwd ? fwd.split(',')[0].trim() : request.ip;

    const key = `login-rl:${clientIp}`;
    const allowed = await this.rateLimitService.hit(key);

    if (!allowed) {
      throw new TooManyRequestsException('Too many login attempts, try again later.');
    }
    return true;
  }
}

// ---------- rate-limit.service.ts ----------
import { Injectable, Logger } from '@nestjs/common';
import Redis from 'ioredis';

const MAX_ATTEMPTS = 5;
const WINDOW_SECONDS = 60;

@Injectable()
export class RateLimitService {
  private readonly logger = new Logger(RateLimitService.name);
  // In-memory fallback: per-process, so it does NOT survive restarts and is
  // NOT shared across replicas.
  private readonly memoryFallback = new Map<string, number>();

  constructor(private readonly redis: Redis) {}

  async hit(key: string): Promise<boolean> {
    try {
      const count = await this.redis.incr(key);
      if (count === 1) {
        await this.redis.expire(key, WINDOW_SECONDS);
      }
      return count <= MAX_ATTEMPTS;
    } catch (err) {
      // Redis is down/unreachable: log it and fall back to admitting the
      // request via a local in-memory counter instead of rejecting it.
      this.logger.error(err);
      const current = this.memoryFallback.get(key) ?? 0;
      this.memoryFallback.set(key, current + 1);
      return true; // fail OPEN — request is let through despite the outage
    }
  }
}

